  9→export const loader = async ({ request }: LoaderFunctionArgs) => {
 10→  const { session } = await authenticate.admin(request);
 11→  const shop = session.shop;
 12→
 13→  const [config, subscription] = await Promise.all([
 14→    db.recommenderConfig.findUnique({ where: { shop } }),
 15→    db.subscription.findUnique({ where: { shop } }),
 16→  ]);
 17→
 18→  const plan = getPlan(subscription?.planId ?? "free");
 19→
 20→  return {
 21→    config: config ?? { enabled: false, algorithm: "basic", bodyTypes: "[]", sizingRules: "{}" },
