import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface LocalConfig {
  displayMode: string;
  position: string;
  triggerType: string;
  primaryColor: string;
  successColor: string;
  errorColor: string;
  backgroundColor: string;
  textColor: string;
  borderRadius: string;
  heading: string;
  placeholder: string;
  buttonText: string;
  successMessage: string;
  errorMessage: string;
  showRecommender: boolean;
  customCss: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });

  return {
    config: config ?? {
      displayMode: "popup",
      position: "bottom-right",
      triggerType: "button",
      primaryColor: "#000000",
      successColor: "#16a34a",
      errorColor: "#dc2626",
      backgroundColor: "#ffffff",
      textColor: "#111111",
      borderRadius: "8",
      heading: "Size Guide",
      placeholder: "Select your size",
      buttonText: "Find My Size",
      successMessage: "This size should fit you well!",
      errorMessage: "We couldn't determine your size. Please refer to the chart.",
      showRecommender: true,
      customCss: "",
    },
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  try {
    const data = {
      displayMode: (formData.get("displayMode") as string) || "popup",
      position: (formData.get("position") as string) || "bottom-right",
      triggerType: (formData.get("triggerType") as string) || "button",
      primaryColor: (formData.get("primaryColor") as string) || "#000000",
      successColor: (formData.get("successColor") as string) || "#16a34a",
      errorColor: (formData.get("errorColor") as string) || "#dc2626",
      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
      textColor: (formData.get("textColor") as string) || "#111111",
      borderRadius: (formData.get("borderRadius") as string) || "8",
      heading: (formData.get("heading") as string) || "Size Guide",
      placeholder: (formData.get("placeholder") as string) || "Select your size",
      buttonText: (formData.get("buttonText") as string) || "Find My Size",
      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
      showRecommender: formData.get("showRecommender") === "true",
      customCss: (formData.get("customCss") as string) || "",
    };

    await db.widgetConfig.upsert({
      where: { shop: session.shop },
      update: data,
      create: { shop: session.shop, ...data },
    });
    return { ok: true, message: "Widget settings saved" };
  } catch (error) {
    return {
      error: error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
};

// ---------------------------------------------------------------------------
// Shared input styles
// ---------------------------------------------------------------------------

const INPUT_STYLE: React.CSSProperties = {
  padding: "8px 12px",
  border: "1px solid #8c9196",
  borderRadius: "8px",
  fontSize: "14px",
  width: "100%",
  outline: "none",
  boxSizing: "border-box",
  fontFamily: "inherit",
  color: "#202223",
  backgroundColor: "#fff",
  transition: "border-color 0.2s",
};

const LABEL_STYLE: React.CSSProperties = {
  fontWeight: 600,
  fontSize: "13px",
  color: "#202223",
  marginBottom: "4px",
  display: "block",
};

const FIELD_STYLE: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: "4px",
  width: "100%",
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function FieldLabel({ children }: { children: React.ReactNode }) {
  return <span style={LABEL_STYLE}>{children}</span>;
}

function TextInput({
  value,
  onChange,
  placeholder,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <input
      type="text"
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      style={INPUT_STYLE}
      onFocus={(e) => {
        (e.currentTarget as HTMLInputElement).style.borderColor = "#005bd3";
      }}
      onBlur={(e) => {
        (e.currentTarget as HTMLInputElement).style.borderColor = "#8c9196";
      }}
    />
  );
}

function ColorPickerField({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <s-box padding="base" borderWidth="base" borderRadius="base">
      <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
        <FieldLabel>{label}</FieldLabel>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <div
            style={{
              width: "32px",
              height: "32px",
              borderRadius: "6px",
              backgroundColor: value,
              border: "1px solid #c9cccf",
              position: "relative",
              overflow: "hidden",
              flexShrink: 0,
              cursor: "pointer",
            }}
          >
            <input
              type="color"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              style={{
                position: "absolute",
                inset: 0,
                opacity: 0,
                width: "100%",
                height: "100%",
                cursor: "pointer",
                padding: 0,
                border: "none",
              }}
            />
          </div>
          <input
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            maxLength={7}
            style={{
              ...INPUT_STYLE,
              width: "90px",
              fontFamily: "monospace",
              fontSize: "13px",
            }}
          />
        </div>
      </div>
    </s-box>
  );
}

function DisplayModeCard({
  value,
  label,
  description,
  benefit,
  selected,
  onSelect,
}: {
  value: string;
  label: string;
  description: string;
  benefit: string;
  selected: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      onClick={() => onSelect(value)}
      style={{
        flex: "1 1 0",
        padding: "16px",
        borderRadius: "8px",
        border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
        backgroundColor: selected ? "#f0f5ff" : "#fff",
        cursor: "pointer",
        transition: "border-color 0.2s, background-color 0.2s",
        minWidth: "140px",
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <div
            style={{
              width: "10px",
              height: "10px",
              borderRadius: "50%",
              border: selected ? "3px solid #005bd3" : "2px solid #8c9196",
              backgroundColor: selected ? "#005bd3" : "transparent",
              flexShrink: 0,
            }}
          />
          <span style={{ fontWeight: 600, fontSize: "14px", color: "#202223" }}>
            {label}
          </span>
          {selected && (
            <span
              style={{
                fontSize: "11px",
                backgroundColor: "#005bd3",
                color: "#fff",
                borderRadius: "4px",
                padding: "1px 6px",
                marginLeft: "auto",
              }}
            >
              Active
            </span>
          )}
        </div>
        <span style={{ fontSize: "13px", color: "#6d7175" }}>{description}</span>
        <span style={{ fontSize: "12px", color: "#005bd3", fontWeight: 500 }}>
          Best for: {benefit}
        </span>
      </div>
    </div>
  );
}

function PositionGrid({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) {
  const positions = [
    { id: "top-left", label: "Top Left" },
    { id: "top-right", label: "Top Right" },
    { id: "bottom-left", label: "Bottom Left" },
    { id: "bottom-right", label: "Bottom Right" },
  ];

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "1fr 1fr",
        gap: "8px",
        maxWidth: "320px",
      }}
    >
      {positions.map((pos) => {
        const selected = value === pos.id;
        return (
          <div
            key={pos.id}
            onClick={() => onChange(pos.id)}
            style={{
              padding: "12px 16px",
              borderRadius: "8px",
              border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
              backgroundColor: selected ? "#f0f5ff" : "#fff",
              cursor: "pointer",
              textAlign: "center",
              fontSize: "13px",
              fontWeight: selected ? 600 : 400,
              color: selected ? "#005bd3" : "#202223",
              transition: "all 0.15s",
            }}
          >
            {pos.label}
          </div>
        );
      })}
    </div>
  );
}

function TriggerTypeSelector({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) {
  const types = [
    { id: "button", label: "Button", desc: "Prominent CTA button" },
    { id: "link", label: "Link", desc: "Subtle text link" },
    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
  ];

  return (
    <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
      {types.map((t) => {
        const selected = value === t.id;
        return (
          <div
            key={t.id}
            onClick={() => onChange(t.id)}
            style={{
              padding: "10px 16px",
              borderRadius: "8px",
              border: selected ? "2px solid #005bd3" : "1px solid #c9cccf",
              backgroundColor: selected ? "#f0f5ff" : "#fff",
              cursor: "pointer",
              transition: "all 0.15s",
            }}
          >
            <div style={{ fontWeight: 600, fontSize: "13px", color: selected ? "#005bd3" : "#202223" }}>
              {t.label}
            </div>
            <div style={{ fontSize: "12px", color: "#6d7175", marginTop: "2px" }}>
              {t.desc}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Live Preview
// ---------------------------------------------------------------------------

function WidgetPreview({ config }: { config: LocalConfig }) {
  const radius = `${config.borderRadius}px`;

  return (
    <div
      style={{
        backgroundColor: config.backgroundColor,
        borderRadius: radius,
        border: `1px solid ${config.primaryColor}33`,
        padding: "20px",
        fontFamily: "system-ui, sans-serif",
        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
        maxWidth: "320px",
        width: "100%",
      }}
    >
      {/* Header */}
      <div
        style={{
          borderBottom: `1px solid ${config.primaryColor}22`,
          paddingBottom: "12px",
          marginBottom: "16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span
          style={{
            fontSize: "16px",
            fontWeight: 700,
            color: config.textColor,
          }}
        >
          {config.heading || "Size Guide"}
        </span>
        <span
          style={{
            fontSize: "18px",
            color: "#8c9196",
            cursor: "pointer",
            lineHeight: 1,
          }}
        >
          ×
        </span>
      </div>

      {/* Size Chart Table */}
      <div
        style={{
          borderRadius: "6px",
          overflow: "hidden",
          border: "1px solid #e3e5e7",
          marginBottom: "16px",
        }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
          <thead>
            <tr style={{ backgroundColor: `${config.primaryColor}15` }}>
              {["Size", "S", "M", "L", "XL"].map((h) => (
                <th
                  key={h}
                  style={{
                    padding: "8px 10px",
                    textAlign: "center",
                    fontWeight: 600,
                    color: config.textColor,
                    borderRight: "1px solid #e3e5e7",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { label: "Bust", values: ["32", "34", "36", "38"] },
              { label: "Waist", values: ["26", "28", "30", "32"] },
              { label: "Hips", values: ["34", "36", "38", "40"] },
            ].map((row, ri) => (
              <tr
                key={row.label}
                style={{ backgroundColor: ri % 2 === 0 ? "#fff" : "#f9fafb" }}
              >
                <td
                  style={{
                    padding: "7px 10px",
                    fontWeight: 600,
                    color: config.textColor,
                    borderRight: "1px solid #e3e5e7",
                    borderTop: "1px solid #e3e5e7",
                    fontSize: "11px",
                  }}
                >
                  {row.label}
                </td>
                {row.values.map((v, vi) => (
                  <td
                    key={vi}
                    style={{
                      padding: "7px 10px",
                      textAlign: "center",
                      color: config.textColor,
                      borderRight: "1px solid #e3e5e7",
                      borderTop: "1px solid #e3e5e7",
                      fontSize: "11px",
                    }}
                  >
                    {v}"
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* CTA Button */}
      {config.showRecommender && (
        <button
          style={{
            width: "100%",
            padding: "10px 16px",
            backgroundColor: config.primaryColor,
            color: "#fff",
            border: "none",
            borderRadius: radius,
            fontSize: "14px",
            fontWeight: 600,
            cursor: "pointer",
            marginBottom: "12px",
          }}
        >
          {config.buttonText || "Find My Size"}
        </button>
      )}

      {/* Success Message */}
      <div
        style={{
          backgroundColor: `${config.successColor}15`,
          border: `1px solid ${config.successColor}40`,
          borderRadius: "6px",
          padding: "10px 12px",
          display: "flex",
          alignItems: "flex-start",
          gap: "8px",
        }}
      >
        <span style={{ color: config.successColor, fontSize: "14px", flexShrink: 0 }}>✓</span>
        <span style={{ fontSize: "12px", color: config.textColor, lineHeight: 1.4 }}>
          {config.successMessage || "This size should fit you well!"}
        </span>
      </div>

      {/* Footer badge */}
      <div
        style={{
          marginTop: "12px",
          textAlign: "center",
          fontSize: "10px",
          color: "#8c9196",
        }}
      >
        Powered by Size Chart & Recommender
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export default function WidgetCustomizer() {
  const { config: serverConfig } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [config, setConfig] = useState<LocalConfig>({
    displayMode: serverConfig.displayMode,
    position: serverConfig.position,
    triggerType: serverConfig.triggerType,
    primaryColor: serverConfig.primaryColor,
    successColor: serverConfig.successColor,
    errorColor: serverConfig.errorColor,
    backgroundColor: serverConfig.backgroundColor,
    textColor: serverConfig.textColor,
    borderRadius: serverConfig.borderRadius,
    heading: serverConfig.heading,
    placeholder: serverConfig.placeholder,
    buttonText: serverConfig.buttonText,
    successMessage: serverConfig.successMessage,
    errorMessage: serverConfig.errorMessage,
    showRecommender: serverConfig.showRecommender,
    customCss: serverConfig.customCss,
  });

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
    setConfig((prev) => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    const formData = new FormData();
    formData.set("displayMode", config.displayMode);
    formData.set("position", config.position);
    formData.set("triggerType", config.triggerType);
    formData.set("primaryColor", config.primaryColor);
    formData.set("successColor", config.successColor);
    formData.set("errorColor", config.errorColor);
    formData.set("backgroundColor", config.backgroundColor);
    formData.set("textColor", config.textColor);
    formData.set("borderRadius", config.borderRadius);
    formData.set("heading", config.heading);
    formData.set("placeholder", config.placeholder);
    formData.set("buttonText", config.buttonText);
    formData.set("successMessage", config.successMessage);
    formData.set("errorMessage", config.errorMessage);
    formData.set("showRecommender", config.showRecommender ? "true" : "false");
    formData.set("customCss", config.customCss);
    fetcher.submit(formData, { method: "post" });
  };

  const showPosition = config.displayMode === "popup" || config.displayMode === "both";

  return (
    <s-page heading="Widget Customizer">

      {/* ------------------------------------------------------------------ */}
      {/* Page-level save action (primary CTA in page header area)           */}
      {/* ------------------------------------------------------------------ */}
      <s-section>
        <s-stack direction="inline" gap="base">
          <s-stack direction="block" gap="small-100">
            <s-paragraph>
              Configure how size charts and the AI recommender appear on your storefront. Changes preview instantly on the right.
            </s-paragraph>
          </s-stack>
          <s-button variant="primary" onClick={handleSave} loading={isLoading}>
            Save changes
          </s-button>
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 1 — Display Mode                                           */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Display Mode">
        <s-stack direction="block" gap="base">
          <s-paragraph>
            Choose how the size chart widget appears on product pages.
          </s-paragraph>
          <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
            <DisplayModeCard
              value="popup"
              label="Popup"
              description="Opens as a modal overlay when triggered"
              benefit="clean product pages"
              selected={config.displayMode === "popup"}
              onSelect={(v) => updateConfig("displayMode", v)}
            />
            <DisplayModeCard
              value="inline"
              label="Inline"
              description="Embedded directly in the product page"
              benefit="detailed size info"
              selected={config.displayMode === "inline"}
              onSelect={(v) => updateConfig("displayMode", v)}
            />
            <DisplayModeCard
              value="both"
              label="Both"
              description="Inline summary with popup for full chart"
              benefit="maximum visibility"
              selected={config.displayMode === "both"}
              onSelect={(v) => updateConfig("displayMode", v)}
            />
          </div>
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 2 — Trigger Settings                                       */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Trigger Settings">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="small-200">
            <s-heading>Trigger Style</s-heading>
            <s-paragraph>
              How customers open the size chart widget.
            </s-paragraph>
            <TriggerTypeSelector
              value={config.triggerType}
              onChange={(v) => updateConfig("triggerType", v)}
            />
          </s-stack>

          {showPosition && (
            <s-stack direction="block" gap="small-200">
              <s-heading>Popup Position</s-heading>
              <s-paragraph>
                Where the popup appears on the screen.
              </s-paragraph>
              <PositionGrid
                value={config.position}
                onChange={(v) => updateConfig("position", v)}
              />
            </s-stack>
          )}
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 3 — Colors                                                 */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Colors">
        <s-stack direction="block" gap="base">
          <s-paragraph>
            Customize the widget color scheme to match your brand.
          </s-paragraph>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))",
              gap: "12px",
            }}
          >
            <ColorPickerField
              label="Primary Color"
              value={config.primaryColor}
              onChange={(v) => updateConfig("primaryColor", v)}
            />
            <ColorPickerField
              label="Background Color"
              value={config.backgroundColor}
              onChange={(v) => updateConfig("backgroundColor", v)}
            />
            <ColorPickerField
              label="Text Color"
              value={config.textColor}
              onChange={(v) => updateConfig("textColor", v)}
            />
            <ColorPickerField
              label="Success Color"
              value={config.successColor}
              onChange={(v) => updateConfig("successColor", v)}
            />
            <ColorPickerField
              label="Error Color"
              value={config.errorColor}
              onChange={(v) => updateConfig("errorColor", v)}
            />
          </div>
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 4 — Typography & Spacing                                   */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Typography & Spacing">
        <s-stack direction="block" gap="base">
          <s-paragraph>
            Control the visual rounding of the widget corners.
          </s-paragraph>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <div style={FIELD_STYLE}>
                <FieldLabel>Border Radius (px)</FieldLabel>
                <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
                  <input
                    type="range"
                    min="0"
                    max="24"
                    value={config.borderRadius}
                    onChange={(e) => updateConfig("borderRadius", e.target.value)}
                    style={{ flex: 1, accentColor: "#005bd3", cursor: "pointer" }}
                  />
                  <input
                    type="number"
                    min="0"
                    max="24"
                    value={config.borderRadius}
                    onChange={(e) => updateConfig("borderRadius", e.target.value)}
                    style={{ ...INPUT_STYLE, width: "60px" }}
                  />
                </div>
              </div>

              {/* Border radius preview */}
              <div style={{ display: "flex", gap: "12px", alignItems: "center", flexWrap: "wrap" }}>
                {["0", "4", "8", "12", "24"].map((r) => (
                  <div
                    key={r}
                    onClick={() => updateConfig("borderRadius", r)}
                    title={`${r}px`}
                    style={{
                      width: "40px",
                      height: "40px",
                      backgroundColor: config.borderRadius === r ? config.primaryColor : "#e3e5e7",
                      borderRadius: `${r}px`,
                      cursor: "pointer",
                      transition: "all 0.15s",
                      border: config.borderRadius === r ? `2px solid ${config.primaryColor}` : "2px solid transparent",
                    }}
                  />
                ))}
                <s-text tone="neutral">{config.borderRadius}px</s-text>
              </div>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 5 — Text & Messages                                        */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Text & Messages">
        <s-stack direction="block" gap="base">
          <s-paragraph>
            Customize the copy that appears in the widget.
          </s-paragraph>
          <s-stack direction="block" gap="base">

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <div style={FIELD_STYLE}>
                <FieldLabel>Widget Heading</FieldLabel>
                <TextInput
                  value={config.heading}
                  onChange={(v) => updateConfig("heading", v)}
                  placeholder="Size Guide"
                />
              </div>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <div style={FIELD_STYLE}>
                <FieldLabel>Button Text</FieldLabel>
                <TextInput
                  value={config.buttonText}
                  onChange={(v) => updateConfig("buttonText", v)}
                  placeholder="Find My Size"
                />
              </div>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <div style={FIELD_STYLE}>
                <FieldLabel>Placeholder Text</FieldLabel>
                <TextInput
                  value={config.placeholder}
                  onChange={(v) => updateConfig("placeholder", v)}
                  placeholder="Select your size"
                />
              </div>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <div style={FIELD_STYLE}>
                <FieldLabel>Success Message</FieldLabel>
                <TextInput
                  value={config.successMessage}
                  onChange={(v) => updateConfig("successMessage", v)}
                  placeholder="This size should fit you well!"
                />
                <s-text tone="neutral">Shown after a successful size recommendation</s-text>
              </div>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <div style={FIELD_STYLE}>
                <FieldLabel>Error Message</FieldLabel>
                <TextInput
                  value={config.errorMessage}
                  onChange={(v) => updateConfig("errorMessage", v)}
                  placeholder="We couldn't determine your size. Please refer to the chart."
                />
                <s-text tone="neutral">Shown when a recommendation cannot be made</s-text>
              </div>
            </s-box>

          </s-stack>
        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Section 6 — Features                                               */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Features">
        <s-stack direction="block" gap="base">

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
                <input
                  type="checkbox"
                  id="showRecommender"
                  checked={config.showRecommender}
                  onChange={(e) => updateConfig("showRecommender", e.target.checked)}
                  style={{
                    width: "18px",
                    height: "18px",
                    marginTop: "1px",
                    cursor: "pointer",
                    accentColor: "#005bd3",
                    flexShrink: 0,
                  }}
                />
                <div>
                  <label
                    htmlFor="showRecommender"
                    style={{ fontWeight: 600, fontSize: "14px", color: "#202223", cursor: "pointer", display: "block" }}
                  >
                    Show AI Recommender
                  </label>
                  <s-text tone="neutral">
                    Display the "Find My Size" button that lets customers get a personalized size recommendation based on their measurements.
                  </s-text>
                  {config.showRecommender && (
                    <s-badge tone="success">Enabled</s-badge>
                  )}
                </div>
              </div>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <div style={FIELD_STYLE}>
                <FieldLabel>Custom CSS</FieldLabel>
                <s-text tone="neutral">
                  Advanced: inject custom styles directly into the widget. Use sparingly.
                </s-text>
                <textarea
                  value={config.customCss}
                  onChange={(e) => updateConfig("customCss", e.target.value)}
                  rows={6}
                  placeholder={`.size-chart-widget {\n  /* custom styles */\n}`}
                  style={{
                    ...INPUT_STYLE,
                    fontFamily: "'Courier New', Courier, monospace",
                    fontSize: "12px",
                    resize: "vertical",
                    minHeight: "120px",
                  }}
                />
              </div>
            </s-stack>
          </s-box>

        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Bottom Save                                                         */}
      {/* ------------------------------------------------------------------ */}
      <s-section>
        <s-stack direction="inline" gap="base">
          <s-button variant="primary" onClick={handleSave} loading={isLoading}>
            Save changes
          </s-button>
          <s-text tone="neutral">All settings affect how the widget appears on your storefront.</s-text>
        </s-stack>
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Live Preview                                                */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Live Preview">
        <s-stack direction="block" gap="base">
          <s-paragraph>
            Updates instantly as you change settings.
          </s-paragraph>
          <WidgetPreview config={config} />
        </s-stack>
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Current Settings Summary                                   */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Current Settings">
        <s-stack direction="block" gap="small-200">
          <s-stack direction="inline" gap="small-100">
            <s-text tone="neutral">Mode:</s-text>
            <s-badge tone="neutral">{config.displayMode}</s-badge>
          </s-stack>
          <s-stack direction="inline" gap="small-100">
            <s-text tone="neutral">Trigger:</s-text>
            <s-badge tone="neutral">{config.triggerType}</s-badge>
          </s-stack>
          {showPosition && (
            <s-stack direction="inline" gap="small-100">
              <s-text tone="neutral">Position:</s-text>
              <s-badge tone="neutral">{config.position}</s-badge>
            </s-stack>
          )}
          <s-stack direction="inline" gap="small-100">
            <s-text tone="neutral">AI Recommender:</s-text>
            <s-badge tone={config.showRecommender ? "success" : "neutral"}>
              {config.showRecommender ? "On" : "Off"}
            </s-badge>
          </s-stack>
          <s-stack direction="inline" gap="small-100">
            <s-text tone="neutral">Border radius:</s-text>
            <s-text>{config.borderRadius}px</s-text>
          </s-stack>
        </s-stack>
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Display Mode Tips                                          */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Display Mode Guide">
        <s-unordered-list>
          <s-list-item>
            <s-text>Popup</s-text> — Clean product pages, chart opens on demand. Ideal for minimalist themes.
          </s-list-item>
          <s-list-item>
            <s-text>Inline</s-text> — Chart always visible on page. Best for fashion brands with complex charts.
          </s-list-item>
          <s-list-item>
            <s-text>Both</s-text> — Inline summary with link to full popup. Maximum visibility without clutter.
          </s-list-item>
        </s-unordered-list>
      </s-section>

    </s-page>
  );
}

