 799→                    key={r}
 800→                    onClick={() => updateConfig("borderRadius", r)}
 801→                    title={`${r}px`}
 802→                    style={{
 803→                      width: "40px",
 804→                      height: "40px",
 805→                      backgroundColor: config.borderRadius === r ? config.primaryColor : "#e3e5e7",
 806→                      borderRadius: `${r}px`,
 807→                      cursor: "pointer",
 808→                      transition: "all 0.15s",
 809→                      border: config.borderRadius === r ? `2px solid ${config.primaryColor}` : "2px solid transparent",
 810→                    }}
 811→                  />
 812→                ))}
 813→                <s-text tone="neutral">{config.borderRadius}px</s-text>
 814→              </div>
 815→            </s-stack>
 816→          </s-box>
 817→        </s-stack>
 818→      </s-section>
